// testGoldenBundle exercises the frozen wire: optional values present and absent,
// collections in non canonical order, escaped characters and two evidence items.
func testGoldenBundle(t *testing.T) contract.Bundle {
	t.Helper()
	subject := testSubject()
	observedAt := testTimestamp(t)
	endedAt, err := contract.NewTimestamp(time.Date(2026, 9, 23, 12, 30, 0, 0, time.UTC))
	if err != nil {
		t.Fatalf("NewTimestamp: %v", err)
	}

	requested := contract.RequestedImage("registry.example/app:release")
	rawRegular := contract.RawImageID("registry.example/app@sha256:aaa")
	digestRegular := contract.NormalizedDigest("sha256:aaa")
	rawInit := contract.RawImageID("registry.example/setup@sha256:bbb")

	value := "sha256:aaa"
	valueHash := contract.ValueHash("sha256:bbb")
	escapeProbe := `policy "default" applied \ to values`

	return contract.Bundle{
		SchemaVersion: contract.SchemaVersionSupported,
		Subject:       subject,
		Images: []contract.ImageIdentity{
			{
				ContainerClass:   contract.ContainerRegular,
				ContainerName:    contract.ContainerName("api"),
				RequestedImage:   &requested,
				RawImageID:       &rawRegular,
				NormalizedDigest: &digestRegular,
				Platform:         contract.Platform{OS: "linux", Architecture: "amd64", Status: contract.PlatformKnown},
				ObservedAt:       &observedAt,
			},
			{
				ContainerClass: contract.ContainerInit,
				ContainerName:  contract.ContainerName("setup"),
				RawImageID:     &rawInit,
				Platform:       contract.Platform{Status: contract.PlatformUnknown},
			},
		},
		Evidence: []contract.EvidenceItem{
			{
				Type:       "pod_spec.containers[].image",
				Source:     "sanitized-pods.json",
				SourceHash: contract.SourceHash("sha256:ccc"),
				Locator:    contract.SourceLocator("items[3].spec.containers[0].image"),
				ObservedAt: &observedAt,
				Confidence: contract.ProvenanceUnavailable,
				Scope:      testScope(subject, testContainer()),
				Warnings:   []contract.Warning{},
			},
			{
				Type:       "container_status.image_id",
				Source:     "sanitized-pods.json",
				SourceHash: contract.SourceHash("sha256:ccc"),
				Locator:    contract.SourceLocator("items[3].status.containerStatuses[0].imageID"),
				Value:      &value,
				ValueHash:  &valueHash,
				ObservedAt: &observedAt,
				Confidence: contract.ProvenanceObserved,
				Scope:      testScope(subject, testContainer()),
				Warnings: []contract.Warning{{
					Code:    "redaction_applied",
					Class:   contract.WarningInformational,
					Message: escapeProbe,
				}},
			},
		},
		ObservedContainerClasses: []contract.ContainerClass{
			contract.ContainerRegular,
			contract.ContainerEphemeral,
			contract.ContainerInit,
		},
		Provenance: contract.RunProvenance{
			CollectorVersion: "0.1",
			ParserVersion:    "kubectl-v1.2",
			Ruleset:          contract.RulesetRef{Path: "rules/", Hash: contract.SourceHash("sha256:ddd"), Version: "2026-09"},
			ArgvSanitized:    []string{"get", "pods", "-o", "json", "--namespace", "payments"},
			Inputs:           []contract.InputRef{{Path: "sanitized-pods.json", Hash: contract.SourceHash("sha256:eee")}},
			APIScope: contract.APIScope{
				Namespaces: []contract.Namespace{"payments"},
				Verbs:      []string{"list", "get"},
				Resources:  []string{"pods"},
			},
			StartedAt:       &observedAt,
			EndedAt:         &endedAt,
			Budget:          contract.Budget{WallClock: "5m", Requests: 1000, Objects: 5000, Bytes: 52428800},
			Coverage:        contract.Coverage{Method: contract.CoverageContainerObservation, Termination: contract.TerminationFinished},
			Completeness:    contract.CompletenessComplete,
			Consistency:     contract.ConsistencyPointObservation,
			RedactionPolicy: "default-v1",
			Warnings: []contract.Warning{
				{Code: "tool_failure", Class: contract.WarningInformational, Message: "collector retried the request"},
				{Code: "redaction_applied", Class: contract.WarningInformational, Message: escapeProbe},
			},
			Errors: []string{},
		},
	}
}

func testPartialBundle(t *testing.T) contract.Bundle {
	t.Helper()
	bundle := testBundle(t)
	bundle.ObservedContainerClasses = []contract.ContainerClass{contract.ContainerRegular}
	bundle.Provenance.Completeness = contract.CompletenessPartial
	bundle.Provenance.Errors = []string{"ephemeral containers were not observed"}
	return bundle
}

func testImportBundle(t *testing.T) contract.Bundle {
	t.Helper()
	total := uint64(3)
	bundle := testBundle(t)
	bundle.ObservedContainerClasses = []contract.ContainerClass{}
	bundle.Provenance.ArgvSanitized = []string{"import", "findings.csv"}
	bundle.Provenance.APIScope = contract.APIScope{Namespaces: []contract.Namespace{}, Verbs: []string{}, Resources: []string{}}
	bundle.Provenance.Inputs = []contract.InputRef{{Path: "findings.csv", Hash: contract.SourceHash("sha256:eee")}}
	bundle.Provenance.Coverage = contract.Coverage{
		Method:      contract.CoverageFindingsImport,
		Termination: contract.TerminationFinished,
		Rows:        &contract.CoverageRows{Total: &total, Accepted: 3, Rejected: 0},
	}
	return bundle
}

// testPartialImportBundle is an aborted import that counted one row: §7(a) makes
// it partial with a visible error.
func testPartialImportBundle(t *testing.T) contract.Bundle {
	t.Helper()
	bundle := testImportBundle(t)
	bundle.Provenance.Coverage.Termination = contract.TerminationAborted
	bundle.Provenance.Coverage.Rows = &contract.CoverageRows{Total: nil, Accepted: 1, Rejected: 0}
	bundle.Provenance.Completeness = contract.CompletenessPartial
	bundle.Provenance.Errors = []string{"budget aborted the import"}
	return bundle
}

func canonicalEnvelope(t *testing.T, bundle contract.Bundle) []byte {
	t.Helper()
	encoded, err := CanonicalJSON(bundle)
	if err != nil {
		t.Fatalf("CanonicalJSON: %v", err)
	}
	return encoded
}

func canonicalProjection(t *testing.T, bundle contract.Bundle) []byte {
	t.Helper()
	canonical, err := canonicalBundle(bundle)
	if err != nil {
		t.Fatalf("canonicalBundle: %v", err)
	}
	projection, err := encodeCanonical(hashProjection(canonical))
	if err != nil {
		t.Fatalf("encodeCanonical: %v", err)
	}
	return projection
}

func hashOf(t *testing.T, bundle contract.Bundle) string {
	t.Helper()
	hash, err := HashCanonicalJSON(bundle)
	if err != nil {
		t.Fatalf("HashCanonicalJSON: %v", err)
	}
	return hash
}

func TestCanonicalJSONGoldenVector(t *testing.T) {
	encoded := canonicalEnvelope(t, testGoldenBundle(t))
	if string(encoded) != goldenEnvelope {
		t.Fatalf("the canonical envelope changed.\nwant:\n%s\ngot:\n%s", goldenEnvelope, encoded)
	}
}

func TestHashCanonicalJSONGoldenVector(t *testing.T) {
	bundle := testGoldenBundle(t)
	projection := canonicalProjection(t, bundle)
	if string(projection) != goldenProjection {
		t.Fatalf("the hash projection changed.\nwant:\n%s\ngot:\n%s", goldenProjection, projection)
	}
	hash := hashOf(t, bundle)
	if hash != goldenHash {
		t.Fatalf("the canonical hash changed.\nwant:\n%s\ngot:\n%s", goldenHash, hash)
	}
	digest := sha256.Sum256([]byte(goldenProjection))
	if expected := "sha256:" + hex.EncodeToString(digest[:]); expected != goldenHash {
		t.Fatalf("the golden hash is not the SHA-256 of the golden projection: %s", expected)
	}
}

func TestHashHasRatifiedShape(t *testing.T) {
	hash := hashOf(t, testGoldenBundle(t))
	if !regexp.MustCompile(`^sha256:[0-9a-f]{64}$`).MatchString(hash) {
		t.Fatalf("the digest does not follow sha256:<64 lowercase hex>: %s", hash)
	}
}

func TestProjectionExcludesOperationalMetadata(t *testing.T) {
	projection := string(canonicalProjection(t, testGoldenBundle(t)))
	for _, excluded := range []string{"collector_version", "parser_version", "argv_sanitized", "started_at", "ended_at", "budget", `"version"`} {
		if strings.Contains(projection, excluded) {
			t.Fatalf("the hash projection leaks the excluded metadata %s: %s", excluded, projection)
		}
	}
	for _, included := range []string{"schema_version", "subject", "images", "evidence", "observed_container_classes", "provenance", "ruleset", "inputs", "api_scope", "coverage", "completeness", "consistency", "redaction_policy", "warnings", "errors"} {
		if !strings.Contains(projection, included) {
			t.Fatalf("the hash projection lost the covered field %s: %s", included, projection)
		}
	}
}

func TestEnvelopeAndProjectionAreDifferentDocuments(t *testing.T) {
	bundle := testGoldenBundle(t)
	envelope := canonicalEnvelope(t, bundle)
	projection := canonicalProjection(t, bundle)
	if string(envelope) == string(projection) {
		t.Fatal("the envelope and the hash projection must not be the same document")
	}
	if !strings.Contains(string(envelope), "argv_sanitized") {
		t.Fatal("the envelope must carry the complete provenance")
	}
}

func TestHashIsNotEmbeddedInTheDocuments(t *testing.T) {
	bundle := testGoldenBundle(t)
	hash := hashOf(t, bundle)
	if strings.Contains(string(canonicalEnvelope(t, bundle)), hash) {
		t.Fatal("the digest must not appear inside the envelope")
	}
	if strings.Contains(string(canonicalProjection(t, bundle)), hash) {
		t.Fatal("the digest must not appear inside the projection")
	}
}

func TestCanonicalJSONOrdersCollections(t *testing.T) {
	encoded := canonicalEnvelope(t, testGoldenBundle(t))
	var decoded struct {
		ObservedContainerClasses []string `json:"observed_container_classes"`
		Images                   []struct {
			ContainerClass string `json:"container_class"`
		} `json:"images"`
		Evidence []struct {
			Type string `json:"type"`
		} `json:"evidence"`
		Provenance struct {
			APIScope struct {
				Verbs []string `json:"verbs"`
			} `json:"api_scope"`
			Warnings []struct {
				Code string `json:"code"`
			} `json:"warnings"`
		} `json:"provenance"`
	}
	if err := json.Unmarshal(encoded, &decoded); err != nil {
		t.Fatalf("unmarshal envelope: %v", err)
	}
	classes := make([]string, 0, len(decoded.ObservedContainerClasses))
	for _, class := range decoded.ObservedContainerClasses {
		classes = append(classes, class)
	}
	if !reflect.DeepEqual(classes, []string{"ephemeral", "init", "regular"}) {
		t.Fatalf("observed container classes are not in canonical order: %v", classes)
	}
	if len(decoded.Images) != 2 || decoded.Images[0].ContainerClass != "init" || decoded.Images[1].ContainerClass != "regular" {
		t.Fatalf("images are not ordered by the canonical tuple: %v", decoded.Images)
	}
	if len(decoded.Evidence) != 2 || decoded.Evidence[0].Type != "container_status.image_id" || decoded.Evidence[1].Type != "pod_spec.containers[].image" {
		t.Fatalf("evidence is not ordered by the canonical tuple: %v", decoded.Evidence)
	}
	if !reflect.DeepEqual(decoded.Provenance.APIScope.Verbs, []string{"get", "list"}) {
		t.Fatalf("api_scope.verbs are not in canonical order: %v", decoded.Provenance.APIScope.Verbs)
	}
	if len(decoded.Provenance.Warnings) != 2 ||
		decoded.Provenance.Warnings[0].Code != "redaction_applied" ||
		decoded.Provenance.Warnings[1].Code != "tool_failure" {
		t.Fatalf("warnings are not ordered by (code, class, message): %v", decoded.Provenance.Warnings)
	}
}

func TestCanonicalJSONOrdersErrorsByCanonicalRepresentation(t *testing.T) {
	bundle := testPartialBundle(t)
	bundle.Provenance.Errors = []string{"b message", `a "quoted" message`, "a message"}
	encoded := canonicalEnvelope(t, bundle)
	var decoded struct {
		Provenance struct {
			Errors []string `json:"errors"`
		} `json:"provenance"`
	}
	if err := json.Unmarshal(encoded, &decoded); err != nil {
		t.Fatalf("unmarshal envelope: %v", err)
	}
	want := []string{`a "quoted" message`, "a message", "b message"}
	if !reflect.DeepEqual(decoded.Provenance.Errors, want) {
		t.Fatalf("errors are not ordered by their canonical JSON representation:\nwant %q\ngot  %q", want, decoded.Provenance.Errors)
	}
}

func TestCanonicalJSONIsDeterministicAndDoesNotMutate(t *testing.T) {
	bundle := testGoldenBundle(t)
	reference := testGoldenBundle(t)
	first := canonicalEnvelope(t, bundle)
	second := canonicalEnvelope(t, bundle)
	if !reflect.DeepEqual(first, second) {
		t.Fatal("canonicalizing the same bundle twice produced different bytes")
	}
	if !reflect.DeepEqual(bundle, reference) {
		t.Fatal("canonicalization mutated the bundle it received")
	}

	permuted := testGoldenBundle(t)
	permuted.Images[0], permuted.Images[1] = permuted.Images[1], permuted.Images[0]
	permuted.Evidence[0], permuted.Evidence[1] = permuted.Evidence[1], permuted.Evidence[0]
	permuted.ObservedContainerClasses = []contract.ContainerClass{
		contract.ContainerInit,
		contract.ContainerRegular,
		contract.ContainerEphemeral,
	}
	permuted.Provenance.APIScope.Verbs = []string{"get", "list"}
	permuted.Provenance.Warnings[0], permuted.Provenance.Warnings[1] = permuted.Provenance.Warnings[1], permuted.Provenance.Warnings[0]
	if got := canonicalEnvelope(t, permuted); !reflect.DeepEqual(got, first) {
		t.Fatalf("permuting the collections changed the canonical bytes:\nwant %s\ngot  %s", first, got)
	}
}

func TestCanonicalJSONPreservesDuplicates(t *testing.T) {
	bundle := testGoldenBundle(t)
	duplicated := testGoldenBundle(t)
	duplicated.Evidence = append(duplicated.Evidence, duplicated.Evidence[0])
	encoded := string(canonicalEnvelope(t, duplicated))
	marker := `"locator":"items[3].spec.containers[0].image"`
	if count := strings.Count(encoded, marker); count != 2 {
		t.Fatalf("duplicated evidence must be preserved, found %d occurrences of the locator", count)
	}
	if base := string(canonicalEnvelope(t, bundle)); strings.Count(base, marker) != 1 {
		t.Fatal("the base fixture must contain exactly one occurrence of the locator")
	}
}

// TestCanonicalJSONEmitsAbsentRunTimestampsAsNull covers ADR-0006 §2 for the two
// optional run timestamps: the wire emits null, the envelope changes and the
// digest does not, because §1(a) excludes them from the projection.
func TestCanonicalJSONEmitsAbsentRunTimestampsAsNull(t *testing.T) {
	base := testGoldenBundle(t)
	baseEnvelope := string(canonicalEnvelope(t, base))
	baseHash := hashOf(t, base)

	withoutTimes := testGoldenBundle(t)
	withoutTimes.Provenance.StartedAt = nil
	withoutTimes.Provenance.EndedAt = nil

	encoded := string(canonicalEnvelope(t, withoutTimes))
	if !strings.Contains(encoded, `"started_at":null,"ended_at":null`) {
		t.Fatalf("absent run timestamps must be emitted as null: %s", encoded)
	}
	if encoded == baseEnvelope {
		t.Fatal("removing the run timestamps must change the envelope")
	}
	if hashOf(t, withoutTimes) != baseHash {
		t.Fatal("started_at and ended_at are excluded from the digest, so removing them must keep it")
	}
}

func TestCanonicalJSONKeepsEmptyArraysAndNulls(t *testing.T) {
	encoded := string(canonicalEnvelope(t, testImportBundle(t)))
	for _, empty := range []string{
		`"observed_container_classes":[]`,
		`"namespaces":[]`,
		`"verbs":[]`,
		`"resources":[]`,
		`"warnings":[]`,
		`"errors":[]`,
	} {
		if !strings.Contains(encoded, empty) {
			t.Fatalf("an empty contractual array lost its [] form: %s", empty)
		}
	}
	golden := string(canonicalEnvelope(t, testGoldenBundle(t)))
	if !strings.Contains(golden, `"owner_chain":"deployments/payments-api"`) {
		t.Fatal("an observed owner chain was not emitted")
	}
	if !strings.Contains(golden, `"normalized_digest":null`) {
		t.Fatal("a tag without a proven digest must be emitted as null")
	}
	if !strings.Contains(golden, `"os":null,"architecture":null,"status":"unknown"`) {
		t.Fatal("an unknown platform must emit null os and architecture")
	}
}

func TestCanonicalJSONKeepsRawEscapesAndWireShape(t *testing.T) {
	encoded := string(canonicalEnvelope(t, testGoldenBundle(t)))
	if !strings.Contains(encoded, `\"default\"`) || !strings.Contains(encoded, `\\`) {
		t.Fatalf("quotes and backslashes are not escaped as JSON requires: %s", encoded)
	}
	if !strings.HasPrefix(encoded, `{"schema_version":"0.1","subject":{`) {
		t.Fatalf("the envelope does not start with the frozen key order: %s", encoded)
	}
	if strings.Contains(encoded, `\u003c`) || strings.Contains(encoded, `\u0026`) {
		t.Fatal("the encoder must not escape HTML")
	}
}

func TestCanonicalJSONDoesNotEscapeHTML(t *testing.T) {
	bundle := testGoldenBundle(t)
	value := "a < b & c > d"
	bundle.Evidence[1].Value = &value
	encoded := string(canonicalEnvelope(t, bundle))
	if !strings.Contains(encoded, `"value":"a < b & c > d"`) {
		t.Fatalf("the canonical bytes escaped HTML characters: %s", encoded)
	}
	if strings.Contains(encoded, `\u003c`) || strings.Contains(encoded, `\u0026`) {
		t.Fatal("the canonical encoder must not escape HTML")
	}
}

func TestCanonicalJSONHasNoBOMWhitespaceOrTrailingNewline(t *testing.T) {
	encoded := canonicalEnvelope(t, testGoldenBundle(t))
	if encoded[0] != '{' {
		t.Fatalf("the envelope does not start with a JSON object: %q", encoded[0])
	}
	if encoded[len(encoded)-1] != '}' {
		t.Fatalf("the envelope does not end with a JSON object: %q", encoded[len(encoded)-1])
	}
	if strings.ContainsAny(string(encoded), "\n\r\t") {
		t.Fatal("the canonical bytes must not contain whitespace outside tokens")
	}
	if strings.HasPrefix(string(encoded), "\ufeff") {
		t.Fatal("the canonical bytes must not carry a BOM")
	}
}

func TestCanonicalRoundTripFromTheEnvelope(t *testing.T) {
	bundle := testGoldenBundle(t)
	envelope := canonicalEnvelope(t, bundle)
	var decoded contract.Bundle
	if err := json.Unmarshal(envelope, &decoded); err != nil {
		t.Fatalf("unmarshal envelope: %v", err)
	}
	if got := canonicalEnvelope(t, decoded); !reflect.DeepEqual(got, envelope) {
		t.Fatalf("re-encoding the decoded envelope changed the bytes:\nwant %s\ngot  %s", envelope, got)
	}
}

func TestCanonicalJSONRejectsInvalidBundles(t *testing.T) {
	mutations := map[string]func(*contract.Bundle){
		"schema version": func(b *contract.Bundle) { b.SchemaVersion = "0.1.0" },
		"nil images":     func(b *contract.Bundle) { b.Images = nil },
		"nil classes":    func(b *contract.Bundle) { b.ObservedContainerClasses = nil },
		"nil argv":       func(b *contract.Bundle) { b.Provenance.ArgvSanitized = nil },
		"nil errors":     func(b *contract.Bundle) { b.Provenance.Errors = nil },
		"missing class": func(b *contract.Bundle) {
			b.ObservedContainerClasses = []contract.ContainerClass{contract.ContainerRegular}
		},
		"invalid utf8": func(b *contract.Bundle) { b.Subject.UID = contract.UID("pod-\xff") },
	}
	for name, mutate := range mutations {
		t.Run(name, func(t *testing.T) {
			bundle := testGoldenBundle(t)
			mutate(&bundle)
			if _, err := CanonicalJSON(bundle); err == nil {
				t.Fatal("CanonicalJSON produced bytes for an invalid bundle")
			}
			if _, err := HashCanonicalJSON(bundle); err == nil {
				t.Fatal("HashCanonicalJSON produced a digest for an invalid bundle")
			}
		})
	}
}

// TestHashScopeCoversProvenanceClaims follows ADR-0006 §1(a) field by field: a
// covered claim changes the digest, an excluded operational metadata does not.
func TestHashScopeCoversProvenanceClaims(t *testing.T) {
	base := testGoldenBundle(t)
	baseHash := hashOf(t, base)
	baseEnvelope := string(canonicalEnvelope(t, base))

	covered := map[string]func(*contract.Bundle){
		"consistency": func(b *contract.Bundle) { b.Provenance.Consistency = contract.ConsistencyNotAtomic },
		"termination": func(b *contract.Bundle) {
			b.Images = b.Images[:1]
			b.ObservedContainerClasses = []contract.ContainerClass{contract.ContainerRegular}
			b.Provenance.Completeness = contract.CompletenessPartial
			b.Provenance.Coverage.Termination = contract.TerminationAborted
			b.Provenance.Errors = []string{"ephemeral containers were not observed"}
		},
		"warnings": func(b *contract.Bundle) {
			b.Provenance.Warnings = append(b.Provenance.Warnings, contract.Warning{Code: "partial_observation", Class: contract.WarningInformational, Message: "one namespace was skipped"})
		},
		"inputs":         func(b *contract.Bundle) { b.Provenance.Inputs[0].Hash = contract.SourceHash("sha256:fff") },
		"api scope":      func(b *contract.Bundle) { b.Provenance.APIScope.Verbs = []string{"get", "list", "watch"} },
		"ruleset hash":   func(b *contract.Bundle) { b.Provenance.Ruleset.Hash = contract.SourceHash("sha256:999") },
		"redaction":      func(b *contract.Bundle) { b.Provenance.RedactionPolicy = "strict-v1" },
		"observed image": func(b *contract.Bundle) { b.Images[0].ContainerName = contract.ContainerName("api-2") },
		"evidence value": func(b *contract.Bundle) { changed := "sha256:zzz"; b.Evidence[1].Value = &changed },
	}
	for name, mutate := range covered {
		t.Run("covered/"+name, func(t *testing.T) {
			bundle := testGoldenBundle(t)
			mutate(&bundle)
			if hashOf(t, bundle) == baseHash {
				t.Fatalf("mutating %s kept the digest, which §1(a) forbids", name)
			}
		})
	}

	excluded := map[string]func(*contract.Bundle){
		"collector_version": func(b *contract.Bundle) { b.Provenance.CollectorVersion = "0.2" },
		"parser_version":    func(b *contract.Bundle) { b.Provenance.ParserVersion = "kubectl-v9" },
		"ruleset_version":   func(b *contract.Bundle) { b.Provenance.Ruleset.Version = "2027-01" },
		"argv_sanitized":    func(b *contract.Bundle) { b.Provenance.ArgvSanitized = []string{"-o", "json", "pods", "get"} },
		"started_at": func(b *contract.Bundle) {
			shifted, err := contract.NewTimestamp(time.Date(2026, 9, 23, 12, 0, 1, 0, time.UTC))
			if err != nil {
				t.Fatalf("NewTimestamp: %v", err)
			}
			b.Provenance.StartedAt = &shifted
		},
		"budget": func(b *contract.Bundle) { b.Provenance.Budget.Requests = 2000 },
	}
	for name, mutate := range excluded {
		t.Run("excluded/"+name, func(t *testing.T) {
			bundle := testGoldenBundle(t)
			mutate(&bundle)
			if hashOf(t, bundle) != baseHash {
				t.Fatalf("mutating the excluded metadata %s changed the digest", name)
			}
			if string(canonicalEnvelope(t, bundle)) == baseEnvelope {
				t.Fatalf("mutating %s did not change the envelope, which carries it", name)
			}
		})
	}
}

// TestHashCoversCoverageCounters isolates the counters of an import: the ratified
// §1(a) projection treats coverage as a claim, never as an operational budget.
func TestHashCoversCoverageCounters(t *testing.T) {
	first := testImportBundle(t)
	second := testImportBundle(t)
	total := uint64(4)
	second.Provenance.Coverage.Rows = &contract.CoverageRows{Total: &total, Accepted: 4, Rejected: 0}
	third := testImportBundle(t)
	thirdTotal := uint64(3)
	third.Provenance.Coverage.Rows = &contract.CoverageRows{Total: &thirdTotal, Accepted: 2, Rejected: 1}
	third.Provenance.Completeness = contract.CompletenessPartial
	third.Provenance.Errors = []string{"row 3 rejected"}

	baseHash := hashOf(t, first)
	if hashOf(t, second) == baseHash {
		t.Fatal("changing the import counters kept the digest")
	}
	if hashOf(t, third) == baseHash {
		t.Fatal("changing accepted and rejected kept the digest")
	}
}

// TestCompletenessCannotBePromotedWithoutChangingTheDigest covers T8: promoting a
// capture to complete, deleting its errors or both must not produce a valid
// digest, and a complete run never shares the digest of an aborted one.
func TestCompletenessCannotBePromotedWithoutChangingTheDigest(t *testing.T) {
	partialHash := hashOf(t, testPartialImportBundle(t))

	if hashOf(t, testImportBundle(t)) == partialHash {
		t.Fatal("a complete import and an aborted import must not share a digest")
	}

	promoted := testPartialImportBundle(t)
	promoted.Provenance.Completeness = contract.CompletenessComplete
	if _, err := HashCanonicalJSON(promoted); err == nil {
		t.Fatal("promoting an aborted capture to complete must be rejected")
	}

	cleaned := testPartialImportBundle(t)
	cleaned.Provenance.Errors = []string{}
	if _, err := HashCanonicalJSON(cleaned); err == nil {
		t.Fatal("removing the visible errors of a partial capture must be rejected")
	}

	both := testPartialImportBundle(t)
	both.Provenance.Completeness = contract.CompletenessComplete
	both.Provenance.Errors = []string{}
	if _, err := HashCanonicalJSON(both); err == nil {
		t.Fatal("promoting completeness and deleting the errors must be rejected")
	}
}

// TestCanonicalJSONAcceptsEveryRatifiedFixture makes sure the canonical encoder
// works on the boundary cases of §7(a) and not only on the happy path.
func TestCanonicalJSONAcceptsEveryRatifiedFixture(t *testing.T) {
	rows := func(total *uint64, accepted, rejected uint64) *contract.CoverageRows {
		return &contract.CoverageRows{Total: total, Accepted: accepted, Rejected: rejected}
	}
	known := func(value uint64) *uint64 { return &value }

	importFixtures := map[string]func(*contract.Bundle){
		"import-complete":    func(b *contract.Bundle) {},
		"import-header-only": func(b *contract.Bundle) { b.Provenance.Coverage.Rows = rows(known(0), 0, 0) },
		"import-rejected-row": func(b *contract.Bundle) {
			b.Provenance.Coverage.Rows = rows(known(3), 2, 1)
			b.Provenance.Completeness = contract.CompletenessPartial
			b.Provenance.Errors = []string{"row 2 rejected"}
		},
		"import-budget-abort": func(b *contract.Bundle) {
			b.Provenance.Coverage.Termination = contract.TerminationAborted
			b.Provenance.Coverage.Rows = rows(nil, 1, 0)
			b.Provenance.Completeness = contract.CompletenessPartial
			b.Provenance.Errors = []string{"budget aborted the import"}
		},
	}
	for name, mutate := range importFixtures {
		t.Run(name, func(t *testing.T) {
			bundle := testImportBundle(t)
			mutate(&bundle)
			assertCanonicalizes(t, bundle)
		})
	}

	observationFixtures := map[string]func(*contract.Bundle){
		"observation-complete-empty-classes": func(b *contract.Bundle) {},
		"observation-missing-class": func(b *contract.Bundle) {
			b.Images = b.Images[:1]
			b.ObservedContainerClasses = []contract.ContainerClass{contract.ContainerRegular}
			b.Provenance.Completeness = contract.CompletenessPartial
			b.Provenance.Errors = []string{"ephemeral containers were not observed"}
		},
		"observation-abort-after-classes": func(b *contract.Bundle) {
			b.Provenance.Coverage.Termination = contract.TerminationAborted
			b.Provenance.Completeness = contract.CompletenessPartial
			b.Provenance.Errors = []string{"budget aborted the collection"}
		},
	}
	for name, mutate := range observationFixtures {
		t.Run(name, func(t *testing.T) {
			bundle := testGoldenBundle(t)
			mutate(&bundle)
			assertCanonicalizes(t, bundle)
		})
	}
}

func assertCanonicalizes(t *testing.T, bundle contract.Bundle) {
	t.Helper()
	if _, err := CanonicalJSON(bundle); err != nil {
		t.Fatalf("CanonicalJSON rejected the ratified fixture: %v", err)
	}
	if _, err := HashCanonicalJSON(bundle); err != nil {
		t.Fatalf("HashCanonicalJSON rejected the ratified fixture: %v", err)
	}
}
